<?php
require_once __DIR__.'/app/lib/Security.php';Security::start();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TechSelectAI Admin</title><style>body{font-family:Inter,Arial,sans-serif;background:#f7f9fc;color:#14213d;margin:0}main{max-width:1180px;margin:auto;padding:32px}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.card,.panel{background:#fff;border:1px solid #e5e7eb;border-radius:16px;padding:18px}.panel{margin-top:28px}table{width:100%;border-collapse:collapse;background:#fff;margin-top:16px}th,td{padding:10px;border-bottom:1px solid #eef2f7;text-align:left;vertical-align:top}button{padding:8px 12px;border:0;border-radius:8px;background:#2563eb;color:white;cursor:pointer}button.secondary{background:#475569}input,select,textarea{width:100%;box-sizing:border-box;padding:9px;border:1px solid #cbd5e1;border-radius:8px;background:#fff}textarea{min-height:120px}label{display:block;font-size:13px;font-weight:700;margin:10px 0 5px}.row{display:grid;grid-template-columns:2fr 1fr 1fr;gap:10px}.muted{color:#64748b;font-size:13px}.badge{display:inline-block;padding:4px 8px;border-radius:999px;background:#eef2ff;font-size:12px}.actions{display:flex;gap:6px;flex-wrap:wrap}.analysis{display:none;margin-top:12px}.analysis.open{display:block}.msg{margin-top:12px;font-weight:650}.ok{color:#166534}.err{color:#b91c1c}@media(max-width:760px){.grid{grid-template-columns:1fr 1fr}.row{grid-template-columns:1fr}table{display:block;overflow:auto}}</style></head><body><main><h1>TechSelectAI Admin</h1><p><a href="/">← Site</a></p><div id="summary" class="grid"></div><h2>Products</h2><table><thead><tr><th>Product</th><th>Vendor</th><th>Category</th><th>Status</th><th>Reviewed</th></tr></thead><tbody id="products"></tbody></table>
<section class="panel"><h2>Public Review Intelligence</h2><p class="muted">Add public sources for review, explicitly approve their access policy, then paste a temporary content snapshot for AI analysis. Snapshot text is sent server-side for analysis and is not stored as review body text.</p><div class="row"><div><label>Product</label><select id="priProduct"></select></div><div><label>Source type</label><select id="priType"><option value="public_forum">Public forum</option><option value="reddit">Reddit</option><option value="app_store">App store</option><option value="vendor_community">Vendor community</option><option value="independent_blog">Independent blog</option><option value="other_public">Other public</option></select></div><div><label>Source name</label><input id="priName" placeholder="e.g. Reddit / App Store"></div></div><label>Public source URL</label><input id="priUrl" type="url" placeholder="https://..."><label>Policy notes</label><input id="priNotes" placeholder="Why this source is permitted/restricted"><p><button onclick="addPriSource()">Add source for review</button></p><div id="priMsg" class="msg"></div><table><thead><tr><th>Product / Source</th><th>Type</th><th>Policy</th><th>Notes</th><th>Actions</th></tr></thead><tbody id="priSources"></tbody></table></section><div id="msg"></div></main><script>
async function api(url,opt={}){opt.headers={...(opt.headers||{}),'Content-Type':'application/json','X-CSRF-Token':localStorage.getItem('csrf')||''};let r=await fetch(url,opt);let d=await r.json().catch(()=>({error:'Invalid server response'}));if(r.status===401){location.href='/login';throw new Error('Sign in required')}if(!r.ok)throw new Error(d.error||'Request failed');return d}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}
let products=[];
async function load(){try{let s=await api('/api/admin/summary');document.getElementById('summary').innerHTML=Object.entries(s).map(([k,v])=>`<div class="card"><small>${esc(k.replaceAll('_',' '))}</small><h2>${esc(v)}</h2></div>`).join('');let p=await api('/api/admin/products');products=p.products;document.getElementById('products').innerHTML=products.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.vendor||'')}</td><td>${esc(x.category||'')}</td><td>${esc(x.status)}</td><td>${esc(x.last_reviewed_at||'')}</td></tr>`).join('');document.getElementById('priProduct').innerHTML=products.filter(x=>x.status==='active').map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('');await loadPriSources()}catch(e){document.getElementById('msg').textContent=e.message}}
async function loadPriSources(){let d=await api('/api/admin/pri/sources');document.getElementById('priSources').innerHTML=d.sources.map(s=>`<tr><td><strong>${esc(s.product)}</strong><br><a href="${esc(s.source_url)}" target="_blank" rel="noopener">${esc(s.source_name||s.source_url)}</a><div id="analysis-${s.id}" class="analysis"><label>Temporary public content snapshot</label><textarea id="content-${s.id}" placeholder="Paste the public review/commentary text to analyze. This text is not stored as the review body."></textarea><button onclick="runPriAnalysis(${s.id},${s.product_id})">Run AI analysis</button></div></td><td>${esc(s.source_type)}</td><td><span class="badge">${esc(s.access_policy)}</span><br><select id="policy-${s.id}"><option value="pending_review" ${s.access_policy==='pending_review'?'selected':''}>pending_review</option><option value="permitted" ${s.access_policy==='permitted'?'selected':''}>permitted</option><option value="restricted" ${s.access_policy==='restricted'?'selected':''}>restricted</option><option value="blocked" ${s.access_policy==='blocked'?'selected':''}>blocked</option></select></td><td><input id="notes-${s.id}" value="${esc(s.access_policy_notes||'')}"></td><td><div class="actions"><button class="secondary" onclick="savePriPolicy(${s.id})">Save policy</button><button onclick="toggleAnalysis(${s.id})" ${s.access_policy!=='permitted'?'disabled title="Permit source first"':''}>Analyze</button></div></td></tr>`).join('')}
async function addPriSource(){let m=document.getElementById('priMsg');try{m.className='msg';m.textContent='Saving...';await api('/api/admin/pri/sources',{method:'POST',body:JSON.stringify({product_id:+document.getElementById('priProduct').value,source_url:document.getElementById('priUrl').value,source_type:document.getElementById('priType').value,source_name:document.getElementById('priName').value,access_policy_notes:document.getElementById('priNotes').value})});document.getElementById('priUrl').value='';document.getElementById('priName').value='';m.className='msg ok';m.textContent='Source added as pending_review.';await loadPriSources()}catch(e){m.className='msg err';m.textContent=e.message}}
async function savePriPolicy(id){let m=document.getElementById('priMsg');try{let policy=document.getElementById('policy-'+id).value;let notes=document.getElementById('notes-'+id).value;await api('/api/admin/pri/sources/'+id,{method:'PATCH',body:JSON.stringify({access_policy:policy,access_policy_notes:notes})});m.className='msg ok';m.textContent='Policy updated and audited.';await loadPriSources()}catch(e){m.className='msg err';m.textContent=e.message}}
function toggleAnalysis(id){document.getElementById('analysis-'+id).classList.toggle('open')}
async function runPriAnalysis(sourceId,productId){let m=document.getElementById('priMsg');let content=document.getElementById('content-'+sourceId).value;try{if(!content.trim())throw new Error('Paste a content snapshot first.');m.className='msg';m.textContent='Analyzing...';let r=await api('/api/admin/pri/analyze',{method:'POST',body:JSON.stringify({product_id:productId,snapshots:[{source_id:sourceId,content}]})});document.getElementById('content-'+sourceId).value='';let i=r.intelligence;m.className='msg ok';m.textContent=i.insufficient_data?`Analysis saved. ${i.sources_analyzed} usable sources so far; more permitted sources/source types are needed before publishing a score.`:`Analysis saved. Current PRI: ${i.score_5}/5 (${i.confidence_label} confidence), ${i.sources_analyzed} usable sources.`}catch(e){m.className='msg err';m.textContent=e.message}}
load();
</script></body></html>